-- Parzellen nach Wunsch, dritte Lieferung (Julian, 19. November: «aber nur
-- erschlossenes Bauland für Wohnen»). Der Ordner hält nur noch Parzellen in
-- Wohn-, Misch- oder Zentrumszonen, die nachweislich erschlossen sind:
--
--   * laut Kanton (Stand der Erschliessung, geodienste.ch, frei als Karte in
--     Obwalden und Uri, in Nidwalden teilweise), «erschlossen»; oder
--   * wo der Kanton nichts liefert (Bern, Schwyz, Luzern; ab 2029 Luzern):
--     ein bestehendes Wohnhaus im Gebäuderegister auf der Parzelle, denn ein
--     Wohnhaus steht nicht ohne Zufahrt, Wasser und Abwasser.
--
-- Unbebaute Parzellen in diesen Zonen ohne amtlichen Stand kommen in einen
-- eigenen Ordner: dort ist offen, ob erschlossen; das weiss nur die Gemeinde.
-- Weggelassen: amtlich «nicht erschlossen», und Parzellen mit nur anderen
-- Gebäuden (Scheune, Garage, Schule) ohne amtlichen Stand.

begin;

alter table public.wunsch_parzelle
  add column if not exists bebaut boolean,
  add column if not exists nachweis text;

update public.wunsch_ordner
   set name = 'Erschlossenes Bauland für Wohnen',
       kriterium = 'über 3''000 m², erschlossen, für Wohnen',
       quelle = 'Wohn-, Misch- und Zentrumszonen (Bauzonen Schweiz). Erschlossen laut Kanton, wo er es veröffentlicht (OW, UR, teils NW), sonst mit Wohnhaus im Gebäuderegister. Fläche aus dem Umriss der amtlichen Vermessung.',
       stand = '19. November 2026'
 where id = '6a1f0c3e-5b7d-4e1a-9c2f-3d8b0e4a7f19';

insert into public.wunsch_ordner (id, name, kriterium, quelle, stand) values
  ('9c4e2b71-3a5f-4d08-b6e2-7f1a0c5d8e42', 'Unbebaut, Erschliessung erfragen', 'über 3''000 m², unbebaut, für Wohnen',
   'Wohn-, Misch- und Zentrumszonen ohne Gebäude im Register. Der Kanton veröffentlicht den Stand der Erschliessung hier nicht; ob erschlossen, weiss die Gemeinde.',
   '19. November 2026')
on conflict (id) do nothing;

delete from public.wunsch_parzelle
 where ordner_id in ('6a1f0c3e-5b7d-4e1a-9c2f-3d8b0e4a7f19', '9c4e2b71-3a5f-4d08-b6e2-7f1a0c5d8e42');

